    12	};
    13	
    14	type PaymentMethodData = {
    15	  paymentMethodTypes?: Record<string, PaymentMethodType>;
    16	  [key: string]: unknown;
    17	};
    18	
    19	function transformIconPaths(data: PaymentMethodData, ecomServerHost: string): PaymentMethodData {
    20	  const baseUrl = `https://${ecomServerHost}/on/demandware.static/Sites-Site/-/-/internal`;
    21	  const methodTypes = data?.paymentMethodTypes;
    22	  if (methodTypes) {
    23	    for (const method of Object.values(methodTypes)) {
    24	      for (const image of method.images ?? []) {
    25	        if (image.src?.startsWith('/icons/')) {
    26	          image.src = `${baseUrl}${image.src}`;
    27	        }
    28	      }
    29	    }
    30	  }
    31	  return data;
    32	}
    33	
    34	type SfPaymentsConfig = {
